<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Visualizer</title>
<style>
  :root{
    --bg:#0f1117;
    --panel:#1a1d27;
    --panel2:#15171f;
    --border:#2d3142;
    --accent:#4ade80;
    --compare:#fbbf24;
    --swap:#ef4444;
    --text:#e5e7eb;
    --muted:#9ca3af;
  }
  *{box-sizing:border-box}
  body{
    margin:0;
    min-height:100vh;
    background:radial-gradient(circle at 50% 0%, #1a1d27 0%, #0b0d13 70%);
    color:var(--text);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    padding:32px 16px;
  }
  h1{
    font-weight:300;
    letter-spacing:3px;
    margin:0 0 6px;
    font-size:28px;
    text-transform:uppercase;
  }
  .subtitle{color:var(--muted);font-size:13px;margin-bottom:24px;letter-spacing:.5px}
  .controls{
    display:flex;gap:10px;margin-bottom:22px;flex-wrap:wrap;justify-content:center;
  }
  button{
    background:var(--panel);
    color:var(--text);
    border:1px solid var(--border);
    padding:10px 22px;
    border-radius:8px;
    cursor:pointer;
    font-size:14px;
    font-weight:500;
    letter-spacing:.5px;
    transition:all .18s ease;
  }
  button:hover:not(:disabled){border-color:var(--accent);color:var(--accent);transform:translateY(-1px)}
  button:disabled{opacity:.5;cursor:not-allowed}
  #sort{
    background:linear-gradient(135deg,#22c55e,#16a34a);
    border:none;color:#06280f;font-weight:600;
  }
  #sort:hover:not(:disabled){filter:brightness(1.12);transform:translateY(-1px)}
  .stage{
    width:100%;
    max-width:920px;
  }
  #bars{
    display:flex;
    align-items:flex-end;
    gap:2px;
    width:100%;
    height:420px;
    background:linear-gradient(180deg,var(--panel),var(--panel2));
    border:1px solid var(--border);
    border-radius:14px;
    padding:18px;
    box-shadow:0 20px 50px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.03);
  }
  .bar{
    flex:1;
    background:linear-gradient(180deg,#60a5fa,#3b82f6);
    border-radius:3px 3px 0 0;
    transition:height .14s ease, background .1s;
    min-width:2px;
    box-shadow:0 0 8px rgba(59,130,246,.25);
  }
  .bar.compare{background:linear-gradient(180deg,#fde68a,#f59e0b);box-shadow:0 0 10px rgba(251,191,36,.5)}
  .bar.swap{background:linear-gradient(180deg,#fca5a5,#dc2626);box-shadow:0 0 12px rgba(239,68,68,.55)}
  .bar.sorted{background:linear-gradient(180deg,#86efac,#22c55e);box-shadow:0 0 10px rgba(74,222,128,.45)}
  .stats{
    margin-top:18px;
    color:var(--muted);
    font-size:13px;
    display:flex;
    gap:28px;
    justify-content:center;
    flex-wrap:wrap;
  }
  .stats b{color:var(--text);font-variant-numeric:tabular-nums}
  .dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--accent);margin-right:6px;vertical-align:middle}
</style>
</head>
<body>
  <h1>Sorting Visualizer</h1>
  <div class="subtitle">Comparison-driven bubble sort — animated one step at a time</div>

  <div class="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>

  <div class="stage">
    <div id="bars"></div>
    <div class="stats">
      <span><span class="dot"></span>Status: <b id="status">Ready</b></span>
      <span>Comparisons: <b id="cmp">0</b></span>
      <span>Swaps: <b id="swp">0</b></span>
      <span>Length: <b id="len">0</b></span>
    </div>
  </div>

<script>
(function(){
  "use strict";

  const barsEl   = document.getElementById('bars');
  const sortBtn  = document.getElementById('sort');
  const shuffleBtn = document.getElementById('shuffle');
  const resetBtn = document.getElementById('reset');
  const cmpEl    = document.getElementById('cmp');
  const swpEl    = document.getElementById('swp');
  const statusEl = document.getElementById('status');
  const lenEl    = document.getElementById('len');

  const DEFAULT_SIZE = 40;
  const STEP_MS = 28;

  // ---- state ----
  let arr = [];
  let initialArray = [];

  // bubble-sort stepper state
  let pos = 0;                 // current comparison index j
  let end = 0;                 // current pass upper bound (exclusive upper index)
  let swappedThisPass = false;
  let done = false;

  let comparisons = 0;
  let swaps = 0;
  let animating = false;

  // ---- helpers ----
  function randomArray(n){
    const a = [];
    for(let i=0;i<n;i++) a.push(Math.floor(Math.random()*95)+5);
    return a;
  }

  function resetSortState(){
    pos = 0;
    end = arr.length > 0 ? arr.length - 1 : 0;
    swappedThisPass = false;
    done = arr.length <= 1;
    comparisons = 0;
    swaps = 0;
    updateStats();
  }

  function render(highlight){
    if(barsEl.children.length !== arr.length){
      barsEl.innerHTML = '';
      for(let i=0;i<arr.length;i++){
        const b = document.createElement('div');
        b.className = 'bar';
        barsEl.appendChild(b);
      }
    }
    const maxV = arr.length ? Math.max.apply(null, arr) : 1;
    const safeMax = Math.max(maxV, 1);
    for(let i=0;i<arr.length;i++){
      const bar = barsEl.children[i];
      const h = (arr[i] / safeMax) * 100;
      bar.style.height = h + '%';
      bar.classList.remove('compare','swap','sorted');
      if(highlight){
        if(highlight.swap && highlight.swap.indexOf(i) !== -1){
          bar.classList.add('swap');
        } else if(highlight.compare && highlight.compare.indexOf(i) !== -1){
          bar.classList.add('compare');
        }
      }
      if(done) bar.classList.add('sorted');
    }
    lenEl.textContent = arr.length;
  }

  function updateStats(){
    cmpEl.textContent = comparisons;
    swpEl.textContent = swaps;
    let s;
    if(done) s = 'Sorted';
    else if(animating) s = 'Sorting…';
    else s = 'Ready';
    statusEl.textContent = s;
  }

  // ---- core sorting stepper (bubble sort) ----
  // One call == exactly one comparison step.
  function sortStep(){
    if(done) return true;
    if(arr.length <= 1){
      done = true;
      render();
      updateStats();
      return true;
    }

    if(pos < end){
      comparisons++;
      const a = arr[pos], b = arr[pos+1];
      let didSwap = false;
      if(a > b){
        arr[pos] = b;
        arr[pos+1] = a;
        swaps++;
        didSwap = true;
        swappedThisPass = true;
        render({compare:[pos,pos+1], swap:[pos,pos+1]});
      } else {
        render({compare:[pos,pos+1]});
      }

      pos++;

      if(pos >= end){
        // pass finished
        if(!swappedThisPass){
          done = true;
          render();
        } else {
          end--;
          pos = 0;
          swappedThisPass = false;
          if(end <= 0){
            done = true;
            render();
          }
        }
      }
    } else {
      done = true;
      render();
    }

    updateStats();
    return done;
  }

  function sorted(){
    for(let i=0;i<arr.length-1;i++){
      if(arr[i] > arr[i+1]) return false;
    }
    return true;
  }

  // ---- public API ----
  function array(){ return arr.slice(); }

  function setArray(a){
    arr = Array.prototype.slice.call(a).map(Number);
    initialArray = arr.slice();
    resetSortState();
    render();
  }

  function shuffle(){
    // Fisher-Yates on a copy
    let a = arr.length ? arr.slice() : randomArray(DEFAULT_SIZE);
    for(let i=a.length-1;i>0;i--){
      const j = Math.floor(Math.random()*(i+1));
      const t = a[i]; a[i] = a[j]; a[j] = t;
    }
    // if accidentally sorted, swap two elements
    let isSorted = true;
    for(let i=0;i<a.length-1;i++){ if(a[i]>a[i+1]){isSorted=false;break;} }
    if(isSorted && a.length >= 2){
      const t = a[0]; a[0] = a[a.length-1]; a[a.length-1] = t;
    }
    setArray(a);
  }

  function reset(){
    if(initialArray.length){
      setArray(initialArray);
    } else {
      setArray(randomArray(DEFAULT_SIZE));
    }
  }

  // ---- animation loop (UI only; sortStep is the source of truth) ----
  async function animate(){
    if(animating) return;
    if(done){ render(); return; }
    animating = true;
    sortBtn.disabled = true;
    updateStats();
    while(!sortStep()){
      await new Promise(function(r){ setTimeout(r, STEP_MS); });
      if(!animating) break; // safety
    }
    animating = false;
    sortBtn.disabled = false;
    render();
    updateStats();
  }

  // expose required API on window
  window.viz = {
    array: array,
    setArray: setArray,
    sortStep: sortStep,
    sorted: sorted
  };

  // ---- events ----
  sortBtn.addEventListener('click', animate);
  shuffleBtn.addEventListener('click', shuffle);
  resetBtn.addEventListener('click', reset);

  // ---- init ----
  setArray(randomArray(DEFAULT_SIZE));
})();
</script>
</body>
</html>
